import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useTranslation } from '../hooks/useTranslation';

// Sample dialogue data (moved outside component to prevent recreation)
const sampleDialogue = {
  id: 'booking_flight',
  title: 'Booking a Flight',
  messages: [
    {
      id: 1,
      sender: 'Agent',
      text: 'Good morning! How can I help you today?',
      translation: 'Bom dia! Como posso ajudá-lo hoje?',
      audio: '/audio/dialogues/booking_flight/01.mp3',
      type: 'other'
    },
    {
      id: 2,
      sender: 'Customer',
      text: 'Hi, I\'d like to book a flight to New York.',
      translation: 'Oi, eu gostaria de reservar um voo para Nova York.',
      audio: '/audio/dialogues/booking_flight/02.mp3',
      type: 'user'
    },
    {
      id: 3,
      sender: 'Agent',
      text: 'Certainly! When would you like to travel?',
      translation: 'Certamente! Quando você gostaria de viajar?',
      audio: '/audio/dialogues/booking_flight/03.mp3',
      type: 'other'
    },
    {
      id: 4,
      sender: 'Customer',
      text: 'Next Friday, if possible.',
      translation: 'Na próxima sexta-feira, se possível.',
      audio: '/audio/dialogues/booking_flight/04.mp3',
      type: 'user'
    }
  ]
};

// Sample themes data (moved outside component to prevent recreation)
const themes = [
  { id: 'booking_flight', title: 'Booking a Flight', description: 'Learn travel vocabulary', level: 'Beginner' },
  { id: 'restaurant', title: 'At the Restaurant', description: 'Ordering food and drinks', level: 'Beginner' },
  { id: 'job_interview', title: 'Job Interview', description: 'Professional conversation', level: 'Intermediate' },
  { id: 'shopping', title: 'Shopping', description: 'Buying clothes and items', level: 'Beginner' },
  { id: 'doctor_visit', title: 'Doctor Visit', description: 'Medical appointments', level: 'Intermediate' },
  { id: 'hotel_checkin', title: 'Hotel Check-in', description: 'Hotel reservations', level: 'Beginner' },
  { id: 'directions', title: 'Asking for Directions', description: 'Navigation and locations', level: 'Beginner' },
  { id: 'phone_call', title: 'Phone Conversation', description: 'Business phone calls', level: 'Advanced' }
];

// Style constants to prevent object recreation
const DISPLAY_STYLES = {
  NONE: { display: 'none' },
  INLINE_FLEX: { display: 'inline-flex' }
};

const Dialogues = () => {
  const { t } = useTranslation();

  // State management
  const [currentDialogue, setCurrentDialogue] = useState('booking_flight');
  const [dialogueData, setDialogueData] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [currentPhraseIndex, setCurrentPhraseIndex] = useState(0);
  const [showTranslations, setShowTranslations] = useState(false);
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [visibleThemes, setVisibleThemes] = useState(4);
  const [showVolumePopup, setShowVolumePopup] = useState(false);

  // Refs
  const audioRefs = useRef([]);
  const dialogueContentRef = useRef(null);
  const progressIntervalRef = useRef(null);

  useEffect(() => {
    // Load dialogue data only once on mount
    setDialogueData(sampleDialogue);
  }, []);

  useEffect(() => {
    // Update audio volume
    audioRefs.current.forEach(audio => {
      if (audio) {
        audio.volume = isMuted ? 0 : volume;
      }
    });
  }, [volume, isMuted]);

  const playDialogue = useCallback(() => {
    if (isPaused) {
      resumeDialogue();
    } else {
      setIsPlaying(true);
      setCurrentPhraseIndex(0);
      playPhrase(0);
    }
  }, [isPaused]);

  const pauseDialogue = useCallback(() => {
    setIsPaused(true);
    setIsPlaying(false);
    audioRefs.current.forEach(audio => {
      if (audio && !audio.paused) {
        audio.pause();
      }
    });
  }, []);

  const resumeDialogue = useCallback(() => {
    setIsPaused(false);
    setIsPlaying(true);
    const currentAudio = audioRefs.current[currentPhraseIndex];
    if (currentAudio) {
      currentAudio.play();
    }
  }, [currentPhraseIndex]);

  const stopDialogue = useCallback(() => {
    setIsPlaying(false);
    setIsPaused(false);
    setCurrentPhraseIndex(0);
    setCurrentTime(0);
    audioRefs.current.forEach(audio => {
      if (audio) {
        audio.pause();
        audio.currentTime = 0;
      }
    });
  }, []);

  const playPhrase = (index) => {
    if (!dialogueData || !dialogueData.messages[index]) return;

    const audio = audioRefs.current[index];
    if (audio) {
      audio.currentTime = 0;
      audio.play().catch(console.error);
      setCurrentPhraseIndex(index);

      audio.onended = () => {
        if (index < dialogueData.messages.length - 1) {
          setTimeout(() => playPhrase(index + 1), 500);
        } else {
          setIsPlaying(false);
          setCurrentPhraseIndex(0);
        }
      };
    }
  };

  const toggleTranslations = () => {
    setShowTranslations(!showTranslations);
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      dialogueContentRef.current?.requestFullscreen?.();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (newVolume) => {
    setVolume(newVolume);
    if (newVolume > 0) {
      setIsMuted(false);
    }
  };

  const loadMoreThemes = () => {
    setVisibleThemes(prev => Math.min(prev + 4, themes.length));
  };

  const showLessThemes = () => {
    setVisibleThemes(4);
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="dialogues-page">
      {/* Page Title */}
      <div className="page-title-container">
        <h1 className="page-title" data-translate="pageTitle">
          {t('pageTitle', 'Dialogues')}
        </h1>
      </div>

      <div className="container">
        {/* Dialogue Container */}
        <div className="dialogue-container" ref={dialogueContentRef}>
          <h2 className="dialogue-title">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
            </svg>
            <span>{dialogueData?.title || 'Loading...'}</span>
          </h2>

          {/* Messages */}
          <div id="dialogue-content" className="dialogue-content">
            {dialogueData?.messages.map((message, index) => (
              <div
                key={message.id}
                className={`message message-${message.type} ${currentPhraseIndex === index && isPlaying ? 'active' : ''}`}
                onClick={() => playPhrase(index)}
              >
                <div className="message-info">
                  <span className="message-sender">{message.sender}</span>
                </div>
                <div className="message-text">{message.text}</div>
                {showTranslations && (
                  <div className="translation-text">{message.translation}</div>
                )}
                <audio
                  ref={el => audioRefs.current[index] = el}
                  src={message.audio}
                  preload="metadata"
                />
              </div>
            ))}
          </div>

          {/* Media Player */}
          <div className="media-player">
            <div className="player-controls">
              <button
                className={`player-btn ${isPlaying && !isPaused ? 'active' : ''}`}
                onClick={playDialogue}
                style={isPlaying && !isPaused ? DISPLAY_STYLES.NONE : DISPLAY_STYLES.INLINE_FLEX}
              >
                <i className="fas fa-play"></i>
              </button>

              <button
                className="player-btn"
                onClick={pauseDialogue}
                style={isPlaying && !isPaused ? DISPLAY_STYLES.INLINE_FLEX : DISPLAY_STYLES.NONE}
              >
                <i className="fas fa-pause"></i>
              </button>

              <button className="player-btn" onClick={stopDialogue}>
                <i className="fas fa-stop"></i>
              </button>

              <button
                className={`player-btn ${showTranslations ? 'active' : ''}`}
                onClick={toggleTranslations}
              >
                <i className="fas fa-language"></i>
              </button>

              <button
                className={`player-btn ${isFullscreen ? 'active' : ''}`}
                onClick={toggleFullscreen}
              >
                <i className={`fas ${isFullscreen ? 'fa-compress' : 'fa-expand'}`}></i>
              </button>

              <div className="volume-control">
                <button
                  className="volume-btn player-btn"
                  onClick={() => setShowVolumePopup(!showVolumePopup)}
                >
                  <i className={`fas ${isMuted ? 'fa-volume-mute' : volume > 0.5 ? 'fa-volume-up' : 'fa-volume-down'}`}></i>
                </button>

                {showVolumePopup && (
                  <div className="volume-popup">
                    <input
                      type="range"
                      min="0"
                      max="1"
                      step="0.1"
                      value={volume}
                      onChange={(e) => handleVolumeChange(parseFloat(e.target.value))}
                      className="volume-slider"
                    />
                    <button onClick={toggleMute} className="mute-btn">
                      {isMuted ? 'Unmute' : 'Mute'}
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="progress-container">
              <div className="progress-bar">
                <div 
                  className="progress-fill"
                  style={{ width: `${totalTime > 0 ? (currentTime / totalTime) * 100 : 0}%` }}
                ></div>
              </div>
              <div className="time-display">
                <span>{formatTime(currentTime)}</span>
                <span>{formatTime(totalTime)}</span>
              </div>
            </div>
          </div>
        </div>

        {/* Theme Selection */}
        <h2 className="section-title" data-translate="chooseTheme">
          {t('chooseTheme', 'Escolha Seu Próximo Tema:')}
        </h2>

        <div className="theme-grid">
          {themes.slice(0, visibleThemes).map(theme => (
            <div
              key={theme.id}
              className="theme-card"
              onClick={() => setCurrentDialogue(theme.id)}
            >
              <div className="theme-header">
                <h3>{theme.title}</h3>
                <span className="theme-level">{theme.level}</span>
              </div>
              <p>{theme.description}</p>
              <button className="theme-btn">
                {t('startDialogue', 'Iniciar Diálogo')}
              </button>
            </div>
          ))}
        </div>

        {/* Theme Controls */}
        <div className="theme-controls">
          {visibleThemes < themes.length && (
            <button onClick={loadMoreThemes} className="theme-control-btn">
              <i className="fas fa-chevron-down"></i>
              <span data-translate="loadMore">{t('loadMore', 'Carregar Mais Temas')}</span>
            </button>
          )}

          {visibleThemes > 4 && (
            <button onClick={showLessThemes} className="theme-control-btn">
              <i className="fas fa-chevron-up"></i>
              <span data-translate="showLess">{t('showLess', 'Mostrar Menos')}</span>
            </button>
          )}
        </div>

        {/* CTA Button */}
        <div className="text-center">
          <a href="#" className="cta-button" data-translate="startLearning">
            {t('startLearning', 'Comece a Aprender Agora!')}
          </a>
        </div>
      </div>

      {/* Styles */}
      <style>{`
        :root {
          --primary: #4361ee;
          --primary-rgb: 67, 97, 238;
          --secondary: #3f37c9;
          --accent: #4cc9f0;
          --dark: #212529;
          --light: #f8f9fa;
          --success: #4ad66d;
          --warning: #f8961e;
          --danger: #ef233c;
          --text: #2b2d42;
          --text-light: #8d99ae;
          --gray-dark: #4a5568;
          --gradient: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);

          --chat-bg: #6495ED;
          --chat-bubble-user: #ffffff;
          --chat-bubble-other: #f8fafc;
          --chat-bubble-user-modern: #d1ffff;
          --chat-bubble-other-modern: #f8fafc;
          --chat-text: var(--text);
          --chat-text-user: #0f172a;
          --chat-text-other: #374151;
          --chat-time: var(--text-light);

          --story-bg: #f0f8ff;
          --story-paragraph: #ffffff;
          --story-text: var(--text);
          --story-highlight: #fff3cd;
          --story-border: rgba(67, 97, 238, 0.1);
        }

        .dialogues-page {
          background-color: #f5f7ff;
          color: var(--text);
          line-height: 1.6;
          min-height: 100vh;
        }

        .page-title-container {
          background-color: #f8f9fa;
          padding: 1.5rem 0;
          margin-bottom: 2rem;
          border-bottom: 1px solid rgba(0, 0, 0, 0.05);
        }

        .page-title {
          font-size: 2.2rem;
          font-weight: 600;
          color: var(--primary);
          text-align: center;
          margin: 0;
          position: relative;
          padding-bottom: 0.5rem;
        }

        .page-title::after {
          content: '';
          position: absolute;
          bottom: 0;
          left: 50%;
          transform: translateX(-50%);
          width: 80px;
          height: 3px;
          background: var(--gradient);
        }

        .container {
          max-width: 1200px;
          margin: 0 auto;
          padding: 0 1.5rem;
          width: 100%;
        }

        .dialogue-container {
          background: var(--story-bg);
          border-radius: 16px;
          padding: 0;
          margin: 3rem 0;
          overflow: hidden;
          box-shadow: 0 8px 32px rgba(240, 248, 255, 0.2);
          border: 1px solid rgba(240, 248, 255, 0.3);
        }

        .dialogue-title {
          background: var(--primary);
          color: white;
          padding: 1.2rem;
          margin: 0;
          display: flex;
          align-items: center;
          gap: 12px;
          font-size: 1.3rem;
          font-weight: 500;
        }

        .dialogue-title svg {
          width: 22px;
          height: 22px;
        }

        .dialogue-content {
          padding: 1.5rem;
          height: 600px;
          overflow-y: auto;
          display: flex;
          flex-direction: column;
          gap: 16px;
        }

        .message {
          max-width: 80%;
          padding: 16px 20px;
          border-radius: 18px;
          position: relative;
          word-wrap: break-word;
          line-height: 1.6;
          font-size: 1.1rem;
          animation: fadeIn 0.3s ease-out;
          cursor: pointer;
          transition: transform 0.2s, box-shadow 0.2s;
          background: transparent;
          border: 1px solid transparent;
        }

        .message:hover {
          transform: translateY(-2px);
          box-shadow: 0 4px 8px rgba(22, 163, 74, 0.3);
        }

        .message.active {
          box-shadow: 0 0 20px rgba(67, 97, 238, 0.5);
          transform: scale(1.02);
        }

        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
