        .message-sender {
          font-weight: 600;
          font-size: 1.2rem;
          color: var(--primary);
        }

        .message-text {
          margin: 8px 0;
          font-size: 1.1rem;
          line-height: 1.6;
        }

        .translation-text {
          margin-top: 12px;
          padding: 12px 16px;
          background: rgba(0, 0, 0, 0.03);
