          font-weight: 600;
          color: var(--primary);
          margin: 0;
        }

        .theme-level {
          background: var(--accent);
          color: white;
          padding: 0.25rem 0.75rem;
          border-radius: 12px;
          font-size: 0.8rem;
          font-weight: 500;
        }

        .theme-card p {
          color: var(--text-light);
          margin-bottom: 1rem;
          line-height: 1.5;
        }

        .theme-btn {
          width: 100%;
          padding: 0.75rem;
          background: var(--primary);
          color: white;
          border: none;
          border-radius: 8px;
          font-weight: 500;
          cursor: pointer;
          transition: background 0.3s;
        }

        .theme-btn:hover {
          background: var(--secondary);
        }

        .theme-controls {
          display: flex;
          justify-content: center;
          gap: 1rem;
          margin: 2rem 0;
        }

        .theme-control-btn {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          padding: 0.75rem 1.5rem;
          background: var(--primary);
          color: white;
          border: none;
          border-radius: 8px;
          font-weight: 500;
          cursor: pointer;
          transition: background 0.3s;
        }

        .theme-control-btn:hover {
          background: var(--secondary);
        }

        .text-center {
          text-align: center;
          margin: 3rem 0;
        }

        .cta-button {
          display: inline-block;
          padding: 1rem 2rem;
          background: var(--gradient);
          color: white;
          text-decoration: none;
          border-radius: 8px;
          font-weight: 600;
          font-size: 1.1rem;
          transition: transform 0.3s, box-shadow 0.3s;
        }

        .cta-button:hover {
          transform: translateY(-2px);
          box-shadow: 0 8px 24px rgba(67, 97, 238, 0.3);
        }

        @media (max-width: 768px) {
          .container {
            padding: 0 1rem;
          }

          .dialogue-content {
            height: 400px;
            padding: 1rem;
          }

          .message {
            max-width: 90%;
            font-size: 1rem;
            padding: 12px 16px;
          }

          .player-controls {
            gap: 15px;
          }

          .player-btn {
            width: 48px;
            height: 48px;
            font-size: 1rem;
          }

          .theme-grid {
            grid-template-columns: 1fr;
            gap: 1rem;
          }

          .page-title {
            font-size: 1.8rem;
          }
        }
